tasks.solution:
function parseApiVersion(string $acceptHeader): ?int
{
    if (preg_match('~application/vnd\.api\+json;\s*version=(\d+)~i', $acceptHeader, $matches)) {
        return (int) $matches[1];
    }

    return null;
}

