function parse_query_string(string $query): array
{
    if ($query === '') {
        return [];
    }

    $result = [];
    foreach (explode('&', $query) as $pair) {
        if ($pair === '') {
            continue;
        }

        $pos = strpos($pair, '=');
        if ($pos === false) {
            $result[urldecode($pair)] = '';
        } else {
            $key = urldecode(substr($pair, 0, $pos));
            $value = urldecode(substr($pair, $pos + 1));
            $result[$key] = $value;
        }
    }

    return $result;
}

